<?php
$selectedId=(int)($_GET['eval_id']??0);
$myEvals=safeRun($pdo,"SELECT ev.*,s.matric_number,s.project_title,s.presentation_date,s.presentation_status,u.full_name FROM evaluations ev JOIN students s ON s.id=ev.student_id JOIN users u ON u.id=s.user_id WHERE ev.evaluator_id=? AND ev.evaluator_role=? AND ev.semester_id=? AND s.semester_id=? ORDER BY ev.status='pending' DESC,ev.created_at DESC",[$lecturerId,$panelRole,$currentSemesterId,$currentSemesterId])->fetchAll();
$selected=null;$criteria=[];$scoreMap=[];
foreach($myEvals as $ev){if((int)$ev['id']===$selectedId)$selected=$ev;}
if($selected){$presentationReady=$selected['presentation_status']==='completed';$criteria=safeRun($pdo,'SELECT * FROM rubric_criteria WHERE rubric_id=? ORDER BY sort_order,id',[$selected['rubric_id']])->fetchAll();$scoreMap=array_column(safeRun($pdo,'SELECT criteria_id,score FROM evaluation_scores WHERE evaluation_id=?',[$selectedId])->fetchAll(),'score','criteria_id');}
?>
<div class="row g-3"><div class="col-lg-4"><div class="card-fy"><div class="section-title"><?= roleLabel($panelRole) ?> Students</div>
<?php foreach($myEvals as $ev): ?><a href="?view=<?= e($panelView) ?>&eval_id=<?= $ev['id'] ?>" class="d-block text-decoration-none p-2 rounded-3 mb-2" style="border:1.5px solid <?= $selectedId===(int)$ev['id']?'var(--theme)':'#eee' ?>"><div class="d-flex justify-content-between"><strong class="small text-dark"><?= e($ev['full_name']) ?></strong><span class="badge-fy badge-<?= statusBadgeColor($ev['status']) ?>"><?= e(ucfirst($ev['status'])) ?></span></div><div class="small text-muted"><?= e($ev['project_title']) ?></div></a><?php endforeach; ?><?php if(!$myEvals): ?><p class="small text-muted mb-0">No evaluations assigned.</p><?php endif; ?></div></div>
<div class="col-lg-8"><?php if(!$selected): ?><div class="card-fy text-center text-muted py-5">Select a student to evaluate.</div><?php else: ?><div class="card-fy">
<div class="d-flex justify-content-between mb-3"><div><div class="section-title mb-0"><?= e($selected['full_name']) ?></div><div class="small text-muted"><?= e($selected['matric_number']) ?> · <?= e($selected['project_title']) ?></div><div class="small mt-1"><i class="fa-regular fa-calendar me-1"></i><?= $selected['presentation_date']?e(date('M j, Y',strtotime($selected['presentation_date']))):'Panel date not scheduled' ?></div></div><span class="badge-fy badge-<?= statusBadgeColor($selected['status']) ?>"><?= e(ucfirst($selected['status'])) ?></span></div>
<form method="post"><?= csrfField() ?><input type="hidden" name="action" value="submit_evaluation"><input type="hidden" name="evaluation_id" value="<?= $selected['id'] ?>"><input type="hidden" name="back_to" value="<?= e($panelView) ?>">
<?php $presentationReady=$presentationReady??true; foreach($criteria as $c): $val=$scoreMap[$c['id']]??''; ?><div class="mb-3"><div class="d-flex justify-content-between small mb-1"><strong><?= e($c['criteria_name']) ?></strong><span>Max <?= e($c['weight']) ?></span></div><input required <?= ($selected['status']==='completed'||!$presentationReady)?'disabled':'' ?> type="number" min="0" max="<?= e($c['weight']) ?>" step="0.5" name="scores[<?= $c['id'] ?>]" value="<?= e($val) ?>" class="form-control-fy w-100"></div><?php endforeach; ?>
<label class="form-label small fw-semibold">Comments</label><textarea <?= ($selected['status']==='completed'||!$presentationReady)?'disabled':'' ?> name="comments" rows="3" class="form-control-fy w-100 mb-3"><?= e($selected['comments']??'') ?></textarea>
<?php if($selected['status']==='completed'): ?><div class="alert alert-success mb-0">This completed evaluation is locked.</div><?php elseif(!$presentationReady): ?><div class="alert alert-warning mb-0">The coordinator must mark the shared panel session as completed before Report Panel or Presentation Panel marks can be submitted.</div><?php else: ?><button class="btn-fy-orange">Submit and lock evaluation</button><?php endif; ?></form></div><?php $backTo=$panelView; require __DIR__.'/detailed-assessment.php'; endif; ?></div></div>
